// СПАЙК S0 — ЗОНД ПОВЕРХНОСТИ КОНТЕКСТА. НЕ МЕРЖИТСЯ.
//
// Существует ради одного: сделать армы РАЗЛИЧИМЫМИ по наблюдаемому поведению. Штатные фикстуры
// станка не годятся — duty-100-50 не читает ctx вовсе (чистый счётчик), short-after-pump на
// синтетической ленте не совершает ни одной сделки. Обе дают одинаковый хеш при ЛЮБОЙ реализации
// поверхности, в том числе сломанной.
//
// Этот зонд читает ВСЁ, что спайк перевёл на персистентный фасад: bar, data.closedCandles,
// indicators, market.oiAsOf/liqAsOf, position, pendingIntent, portfolio, clock, run, params, rng —
// и решает по прочитанному. Совпадение хешей арм здесь = поверхность отдаёт те же значения;
// расхождение или нулевые сделки = не отдаёт.
export default function createStrategyModule() {
  let held = -1;
  function fingerprint(ctx) {
    // Каждое поле участвует в решении: чтение, которое ни на что не влияет, ничего не проверяет.
    let x = 0;
    x += ctx.bar.close + ctx.bar.high - ctx.bar.low + ctx.bar.volume + ctx.bar.open + ctx.bar.ts % 7;
    x += ctx.clock.now() % 11;
    x += ctx.run.seed % 13 + ctx.run.runId.length + ctx.run.mode.length;
    x += Object.keys(ctx.params).length;
    x += ctx.symbol.length;
    x += ctx.portfolio.equity % 17 + ctx.portfolio.openPositions;
    x += ctx.position === null ? 0 : ctx.position.entryPrice % 19 + ctx.position.size + ctx.position.side.length;
    x += ctx.pendingIntent === null ? 0 : ctx.pendingIntent.createdTs % 23;
    const win = ctx.data.closedCandles(5);
    for (const b of win) x += b.close % 29;
    const sma = ctx.indicators.value("sma", 10);
    if (typeof sma === "number") x += sma % 31;
    const legacy = ctx.data.indicatorAsOf("sma_10");
    if (typeof legacy === "number") x += legacy % 37;
    if (ctx.market !== undefined) {
      const oi = ctx.market.oiAsOf();
      if (oi !== undefined) x += oi.oiTotalUsd % 41;
      const liq = ctx.market.liqAsOf();
      if (liq !== undefined) x += (liq.longUsd + liq.shortUsd) % 43;
      x += ctx.market.oiWindow(3).length + ctx.market.liqWindow(3).length;
    }
    x += ctx.rng.next();
    return x;
  }
  return {
    manifest: { id: "spike_ctx_probe", version: "0.1.0" },
    onBarClose(ctx) {
      const x = fingerprint(ctx);
      if (held >= 0) return { kind: "idle" };
      if (Math.floor(x) % 37 === 0) { held = 0; return { kind: "enter", side: "long" }; }
      return { kind: "idle" };
    },
    onPositionBar(ctx) {
      const x = fingerprint(ctx);
      if (held < 0) return { kind: "idle" };
      held += 1;
      if (held >= 20 || Math.floor(x) % 53 === 0) { held = -1; return { kind: "exit", target: "time_exit" }; }
      return { kind: "idle" };
    },
  };
}
